// ─── File: EdgeStackDemo.java ───
// Shows L4 LB → L7 reverse proxy → API gateway → backend, each a distinct concern.
import java.util.*;
import java.util.logging.*;

public class EdgeStackDemo {
    private static final Logger log = Logger.getLogger("Edge");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BackendService loan1 = new BackendService("loan-1");
        BackendService loan2 = new BackendService("loan-2");
        LoadBalancerL4 l4 = new LoadBalancerL4(List.of(loan1, loan2));
        ReverseProxy proxy = new ReverseProxy(l4);
        ApiGateway gateway = new ApiGateway(proxy, 3); // 3 req/min per client

        // Valid authenticated request flows through all layers.
        gateway.handle(new Request("SAV2001", "/api/loans", true));
        gateway.handle(new Request("SAV2001", "/api/loans", true));
        gateway.handle(new Request("SAV2001", "/api/loans", true));
        log.info("--- 4th request exceeds the rate limit ---");
        gateway.handle(new Request("SAV2001", "/api/loans", true));  // rate limited
        log.info("--- unauthenticated request rejected at the gateway ---");
        gateway.handle(new Request("CUR3001", "/api/loans", false)); // no valid JWT
    }
}

// ─── model/Request.java ───
class Request {
    final String clientId, path; final boolean authenticated;
    Request(String clientId, String path, boolean authenticated) {
        this.clientId = clientId; this.path = path; this.authenticated = authenticated;
    }
}

// ─── model/Response.java ───
class Response {
    final int status; final String body;
    Response(int status, String body) { this.status = status; this.body = body; }
}

// ─── gateway/ApiGateway.java (L7: auth, rate limit, routing, aggregation) ───
class ApiGateway {
    private static final Logger log = Logger.getLogger("Edge");
    private final ReverseProxy proxy;
    private final int limitPerMin;
    private final Map<String, Integer> counts = new HashMap<>();
    ApiGateway(ReverseProxy proxy, int limitPerMin) { this.proxy = proxy; this.limitPerMin = limitPerMin; }

    Response handle(Request req) {
        // Concern 1: authentication — API-specific, belongs to the gateway.
        if (!req.authenticated) {
            log.warning(() -> "GATEWAY rejected " + req.clientId + " 401 Unauthorized");
            return new Response(401, "Unauthorized");
        }
        // Concern 2: rate limiting — API-specific.
        int used = counts.merge(req.clientId, 1, Integer::sum);
        if (used > limitPerMin) {
            log.warning(() -> "GATEWAY rate-limited " + req.clientId + " 429 Too Many Requests");
            return new Response(429, "Too Many Requests");
        }
        log.info(() -> "GATEWAY authenticated + under limit (" + used + "/" + limitPerMin
                + ") → forward " + req.path);
        return proxy.forward(req);  // hand down to the reverse proxy layer
    }
}

// ─── proxy/ReverseProxy.java (TLS termination + path routing + shielding) ───
class ReverseProxy {
    private static final Logger log = Logger.getLogger("Edge");
    private final LoadBalancerL4 l4;
    ReverseProxy(LoadBalancerL4 l4) { this.l4 = l4; }
    Response forward(Request req) {
        log.info(() -> "PROXY terminated TLS + routed path " + req.path + " to loan-pool");
        return l4.route(req); // hand down to the L4 load balancer for the pool
    }
}

// ─── l4/LoadBalancerL4.java (distribute by connection count, no payload inspection) ───
class LoadBalancerL4 {
    private static final Logger log = Logger.getLogger("Edge");
    private final List<BackendService> pool;
    private final Map<String, Integer> connections = new HashMap<>();
    LoadBalancerL4(List<BackendService> pool) {
        this.pool = pool;
        for (BackendService b : pool) connections.put(b.name(), 0);
    }
    Response route(Request req) {
        // Least-connections: pick the backend with the fewest active connections.
        BackendService chosen = pool.get(0);
        for (BackendService b : pool) {
            if (connections.get(b.name()) < connections.get(chosen.name())) chosen = b;
        }
        connections.merge(chosen.name(), 1, Integer::sum);
        BackendService fchosen = chosen;
        log.info(() -> "L4 routed to backend " + fchosen.name()
                + " (least-connections, no payload inspection)");
        return chosen.process(req);
    }
}

// ─── backend/BackendService.java (the actual microservice instance) ───
class BackendService {
    private static final Logger log = Logger.getLogger("Edge");
    private final String name;
    BackendService(String name) { this.name = name; }
    String name() { return name; }
    Response process(Request req) {
        log.info(() -> "BACKEND " + name + " served " + req.path + " for " + req.clientId);
        return new Response(200, "loan data from " + name);
    }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
